"},{"date":"2026-07-06","morning":"186.8","evening":"189"},{"date":"2026-07-08","morning":"189.2","evening":"192"},{"date":"2026-07-13","morning":"188.4","evening":"189.4"},{"date":"2026-07-15","morning":"186.8","evening":"190.2"},{"date":"2026-07-19","morning":"189.6","evening":"189.6"},{"date":"2026-07-21","morning":"193","evening":"190"},{"date":"2026-07-27","morning":"188.2","evening":"191"},{"date":"2026-08-25","morning":"190.2","evening":"188.2"},{"date":"2026-08-28","morning":"188.6","evening":"187.8"},{"date":"2026-08-31","morning":"190","evening":"192"}]$source$::jsonb;
 v_dates int;v_total int;v_new int;v_inserted int;
 v_other_before bigint;v_other_after bigint;v_conflict record;v_bad record;
begin
 if not exists(select 1 from auth.users where id=v_user)then
  raise exception 'Target UUID % does not exist in auth.users; nothing inserted',v_user;
 end if;
 if not exists(select 1 from pg_timezone_names where name=v_zone)then raise exception 'Invalid time zone %',v_zone;end if;
 if date '2026-09-01'+(973-974)<>date '2026-08-31'
  or date '2026-09-01'+(173-974)<>date '2024-06-22'
  or date '2024-02-28'+1<>date '2024-02-29'
  or date '2024-02-29'+1<>date '2024-03-01' then raise exception 'Date validation failed';end if;
 select count(*),count(*)*2 into v_dates,v_total
 from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric);
 if v_dates<>219 or v_total<>438 then raise exception 'Invalid source counts: dates %, records %',v_dates,v_total;end if;
 if exists(select 1 from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
   where d.date::date<date '2024-06-22' or d.date::date>date '2026-08-31' or d.morning<=0 or d.evening<=0)
  or exists(select 1 from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
   group by d.date having count(*)<>1)then raise exception 'Invalid source range, duplicate, or weight';end if;
 if not exists(select 1 from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
   where d.date::date=date '2024-06-22' and d.morning=183.2 and d.evening=184.4)
  or not exists(select 1 from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
   where d.date::date=date '2026-08-31' and d.morning=190 and d.evening=192)
  then raise exception 'Source boundary validation failed';end if;

 lock table public.weigh_ins in share row exclusive mode;
 select count(*)into v_other_before from public.weigh_ins where user_id<>v_user;

 with source as(
  select d.date::date measured_date,p.period,p.weight from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
  cross join lateral(values('morning'::text,d.morning),('evening'::text,d.evening))p(period,weight)
 ),compared as(
  select s.measured_date,s.period,s.weight proposed_weight,count(w.id)::int existing_count,
   count(w.id)filter(where w.weight=s.weight)::int exact_count,
   array_agg(w.weight order by w.measured_at,w.id)filter(where w.id is not null)existing_weights
  from source s left join public.weigh_ins w on w.user_id=v_user
   and(w.measured_at at time zone v_zone)::date=s.measured_date and w.period::text=s.period
  group by s.measured_date,s.period,s.weight
 )
 select * into v_conflict from compared where existing_count<>0 and not(existing_count=1 and exact_count=1)
 order by measured_date,case period when 'morning'then 1 else 2 end limit 1;
 if found then raise exception 'Conflict: date %, period %, existing %, proposed %, row count %. Nothing inserted.',
  v_conflict.measured_date,v_conflict.period,v_conflict.existing_weights,v_conflict.proposed_weight,v_conflict.existing_count;end if;

 with source as(
  select d.date::date measured_date,p.period,p.weight,p.hour,p.n from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
  cross join lateral(values('morning'::text,d.morning,8,1),('evening'::text,d.evening,20,2))p(period,weight,hour,n)
 )
 select count(*)into v_new from source s where not exists(select 1 from public.weigh_ins w where w.user_id=v_user
  and(w.measured_at at time zone v_zone)::date=s.measured_date and w.period::text=s.period);

 with source as(
  select d.date::date measured_date,p.period,p.weight,p.hour,p.n from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
  cross join lateral(values('morning'::text,d.morning,8,1),('evening'::text,d.evening,20,2))p(period,weight,hour,n)
 ),added as(
  insert into public.weigh_ins(user_id,measured_at,period,weight,weight_unit,notes)
  select v_user,make_timestamptz(extract(year from s.measured_date)::int,extract(month from s.measured_date)::int,
   extract(day from s.measured_date)::int,s.hour,0,0,v_zone),s.period::public.weigh_in_period,
   s.weight,'lb'::public.weight_unit,'One-time Bodyweight backfill (source date '||s.measured_date||')'
  from source s where not exists(select 1 from public.weigh_ins w where w.user_id=v_user
   and(w.measured_at at time zone v_zone)::date=s.measured_date and w.period::text=s.period)
  order by s.measured_date,s.n returning id
 )
 select count(*)into v_inserted from added;
 if v_inserted<>v_new then raise exception 'Inserted % but expected %',v_inserted,v_new;end if;

 with source as(
  select d.date::date measured_date,p.period,p.weight from jsonb_to_recordset(v_data)d(date text,morning numeric,evening numeric)
  cross join lateral(values('morning'::text,d.morning),('evening'::text,d.evening))p(period,weight)
 )
 select s.measured_date,s.period,s.weight proposed_weight,count(w.id)::int stored_count,
  array_agg(w.weight order by w.id)filter(where w.id is not null)stored_weights into v_bad
 from source s left join public.weigh_ins w on w.user_id=v_user
  and(w.measured_at at time zone v_zone)::date=s.measured_date and w.period::text=s.period
 group by s.measured_date,s.period,s.weight
 having count(w.id)<>1 or count(w.id)filter(where w.weight=s.weight)<>1
 order by s.measured_date,case s.period when 'morning'then 1 else 2 end limit 1;
 if found then raise exception 'Post-check: date %, period %, stored %, proposed %, count %',
  v_bad.measured_date,v_bad.period,v_bad.stored_weights,v_bad.proposed_weight,v_bad.stored_count;end if;
 select count(*)into v_other_after from public.weigh_ins where user_id<>v_user;
 if v_other_after<>v_other_before then raise exception 'Other-user count changed: before %, after %',v_other_before,v_other_after;end if;
 raise notice 'Complete: source dates=%, readings=%, exact already present=%, inserted=%, final exact=438',
  v_dates,v_total,438-v_new,v_inserted;
end
$bodyweight_import$;

